ALTER TABLE "_BlogPostTags" ADD CONSTRAINT "_BlogPostTags_B_fkey" FOREIGN KEY ("B") REFERENCES "tags"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- ═══ Part 2 — Verified database features not representable in schema.prisma ═══

-- subscriptions_billto_xor: a subscription is billed to EXACTLY ONE of an
-- organization or a user. Found in the live database (added outside Prisma);
-- preserved verbatim with its existing name. Prisma does not manage CHECK
-- constraints, so future `migrate diff` runs will neither create nor drop it.
ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_billto_xor" CHECK ((("organizationId" IS NOT NULL) <> ("userId" IS NOT NULL)));
